insert into public.courses (key, category, title, subtitle, description, icon, total_days, pass_score, exam, exam_key, ord)
values ('logic-fallacies', 'thinking', 'Логические уловки в спорах', '7 дней · 12 уловок · сертификат', 'Научись замечать, когда в споре играют нечестно, и спокойно возвращать разговор к сути. 3–5 минут в день.', '🧠',
        7, 9, '[{"id":0,"quote":"Ты хочешь сократить расходы на армию? То есть предлагаешь оставить страну беззащитной?","options":["Ложная дилемма","Соломенное чучело","Скользкая дорожка","Переход на личности"]},{"id":1,"quote":"Не слушайте его советы по бизнесу — он даже машину нормально водить не умеет.","options":["Переход на личности","«Сам такой»","Ложный авторитет","Отвлечение внимания"]},{"id":2,"quote":"Либо мы запускаем проект в этом месяце, либо он вообще никому не будет нужен.","options":["Скользкая дорожка","Поспешное обобщение","Ложная дилемма","Круговое рассуждение"]},{"id":3,"quote":"Если разрешить пересдачи, скоро никто не будет готовиться, и диплом совсем обесценится.","options":["Ложная причина","Скользкая дорожка","Ложная дилемма","Апелляция к большинству"]},{"id":4,"quote":"Популярный певец говорит, что эта диета — лучшая в мире.","options":["Апелляция к большинству","Перекладывание бремени доказательства","Переход на личности","Ложный авторитет"]},{"id":5,"quote":"Половина города уже скачала это приложение — значит, ему можно доверять.","options":["Апелляция к большинству","Ложный авторитет","Поспешное обобщение","Ложная причина"]},{"id":6,"quote":"Ты критикуешь мой отчёт? А в твоём в прошлом месяце было полно ошибок!","options":["Отвлечение внимания","Переход на личности","«Сам такой»","Соломенное чучело"]},{"id":7,"quote":"— Почему подорожал проезд?\n— Давайте лучше поговорим о том, сколько мы сделали для спорта!","options":["«Сам такой»","Отвлечение внимания","Ложная дилемма","Круговое рассуждение"]},{"id":8,"quote":"Два моих знакомых программиста — интроверты. Все программисты интроверты.","options":["Ложная причина","Апелляция к большинству","Соломенное чучело","Поспешное обобщение"]},{"id":9,"quote":"Летом продают больше мороженого — и летом же больше людей тонет. Значит, мороженое опасно!","options":["Ложная причина","Поспешное обобщение","Скользкая дорожка","Круговое рассуждение"]},{"id":10,"quote":"Эта книга мудрая, потому что в ней собрана мудрость.","options":["Перекладывание бремени доказательства","Ложный авторитет","Круговое рассуждение","Ложная дилемма"]},{"id":11,"quote":"Призраки существуют. Пока что никто не доказал обратного.","options":["Круговое рассуждение","Перекладывание бремени доказательства","Апелляция к большинству","Ложная причина"]}]'::jsonb, '[{"answer":1,"explain":"«Сократить расходы» исказили до «оставить беззащитной» — это соломенное чучело."},{"answer":0,"explain":"Умение водить никак не связано с качеством советов по бизнесу. Атакуют человека, а не довод."},{"answer":2,"explain":"Есть и другие варианты: запустить через два месяца, сделать пробную версию. Выбор сузили до двух."},{"answer":1,"explain":"Цепочка от пересдач до обесценивания диплома не подкреплена доказательствами."},{"answer":3,"explain":"Певец не диетолог. Его известность не делает его экспертом по питанию."},{"answer":0,"explain":"Популярность приложения не говорит о его надёжности и безопасности."},{"answer":2,"explain":"Ошибки в чужом отчёте не отменяют ошибок в своём. Критику отбили встречным упрёком."},{"answer":1,"explain":"Спорт не отвечает на вопрос о цене проезда — тему подменили."},{"answer":3,"explain":"Двух знакомых слишком мало, чтобы судить обо всех программистах."},{"answer":0,"explain":"Оба явления вызывает третье — жара. Совпадение не значит, что одно вызывает другое."},{"answer":2,"explain":"Довод повторяет вывод — аргумент ходит по кругу."},{"answer":1,"explain":"Доказывать должен тот, кто утверждает. Отсутствие опровержения — не доказательство."}]'::jsonb, 1)
