insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 1, 'Спорят не с тобой', 'Соломенное чучело и переход на личности', array['strawman', 'ad-hominem']::text[], '[{"type":"intro","icon":"🧠","title":"Добро пожаловать!","text":"Логическая уловка — это приём, который делает аргумент убедительным на вид, но не по сути. За 7 дней разберём 12 самых частых уловок. Сегодня — две, в которых спорят вовсе не с тем, что ты сказал."},{"type":"chat","card":"strawman","messages":[{"name":"Лена","text":"Думаю, детям стоит меньше сидеть в телефонах."},{"name":"Дима","text":"То есть ты предлагаешь отобрать у них гаджеты и вернуться в каменный век?","flag":true},{"name":"Лена","text":"Я такого не говорила…"}],"caption":"Лена сказала «меньше», а Дима спорит с «отобрать всё». С крайней версией спорить легче — поэтому её и подсовывают."},{"type":"concept","card":"strawman","icon":"🎃","title":"Соломенное чучело","definition":"Собеседник пересказывает твою мысль в утрированном виде — и спорит уже с этим пересказом, а не с твоими словами.","signs":["«То есть ты считаешь, что…» — и дальше заметно более крайняя версия","Твои оговорки («иногда», «немного», «в некоторых случаях») исчезают","Тебе приписывают вывод, которого ты не делал"],"counter":"Верни разговор к исходным словам: «Подожди, это не мои слова. Моя мысль была такой: … С ней ты не согласен?»"},{"type":"chat","card":"ad-hominem","messages":[{"name":"Тимур","text":"Нам стоит урезать бюджет на рекламу — она почти не приносит клиентов."},{"name":"Айбек","text":"Ты в компании полгода, а уже учишь нас, как работать?","flag":true}],"caption":"Сколько Тимур работает в компании — ничего не говорит о том, приносит ли реклама клиентов. Довод остался без ответа."},{"type":"concept","card":"ad-hominem","icon":"🎯","title":"Переход на личности","definition":"Вместо того чтобы разобрать аргумент, атакуют того, кто его высказал: возраст, внешность, опыт, прошлые ошибки.","signs":["Обсуждают человека, а не мысль","«Кто бы говорил», «сначала добейся», «что ты понимаешь в свои 20»","Сам довод так и остаётся без ответа"],"counter":"«Допустим, я много в чём неправ. Но что не так с самим аргументом?»","note":"Сомнение в компетенции бывает уместно — например, если медицинский совет даёт человек без медицинского образования. Уловка — когда разговор о личности заменяет разбор довода."}]'::jsonb, '[{"type":"binary","quote":"Ты против нового закона? Значит, тебе плевать на безопасность людей.","trick":true,"explain":"Несогласие с конкретным законом раздули до «плевать на безопасность». Это соломенное чучело."},{"type":"binary","quote":"В твоём расчёте ошибка: расходы ты взял за два месяца, а доходы — за один.","trick":false,"explain":"Критикуют сам расчёт — конкретно и проверяемо. Это честное возражение."},{"type":"choice","quote":"Ты предлагаешь поднять зарплаты учителям? То есть хочешь, чтобы все налоги уходили только на школы?","prompt":"Какая уловка?","options":["Соломенное чучело","Переход на личности","Честное возражение"],"answer":0,"explain":"«Поднять зарплаты» превратили в «все налоги только на школы» — и спорят с преувеличением."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Нурай","text":"Давай по пятницам работать из дома — сэкономим время на дорогу."},{"name":"Руслан","text":"Удалёнка неудобна для общих созвонов."},{"name":"Нурай","text":"Согласна, созвоны можно ставить на другие дни."},{"name":"Руслан","text":"Да ты просто хочешь целый день валяться на диване."}],"answer":3,"explain":"Руслан перестал обсуждать идею и начал приписывать Нурай лень. Это переход на личности."},{"type":"choice","quote":"Какой смысл слушать советы о здоровом питании от человека с лишним весом?","prompt":"Какая уловка?","options":["Соломенное чучело","Переход на личности","Честное возражение"],"answer":1,"explain":"Совет может быть верным или неверным независимо от веса того, кто его даёт. Проверять нужно совет."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«То есть ты хочешь всё запретить?»","label":"Соломенное чучело"},{"quote":"«Сначала заработай столько же, потом советуй»","label":"Переход на личности"},{"quote":"«Покажи данные, на которые опираешься»","label":"Честный вопрос"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 2, 'Только два варианта?', 'Ложная дилемма и скользкая дорожка', array['false-dilemma', 'slippery-slope']::text[], '[{"type":"intro","icon":"🚪","title":"День 2","text":"Сегодня — уловки, которые пугают последствиями. Одна прячет все варианты, кроме двух. Другая рисует катастрофу из одного маленького шага."},{"type":"chat","card":"false-dilemma","messages":[{"name":"Мама","text":"Или ты идёшь на юриста, или будешь всю жизнь без денег.","flag":true},{"name":"Алия","text":"А если я стану хорошим дизайнером?"}],"caption":"Профессий намного больше двух, а доход зависит не только от диплома. Выбор искусственно сузили."},{"type":"concept","card":"false-dilemma","icon":"⚖️","title":"Ложная дилемма","definition":"Выбор сужают до «или—или», хотя на самом деле есть промежуточные и совсем другие варианты.","signs":["«Либо ты с нами, либо против нас»","«Или X, или катастрофа»","Нет места для «частично», «иногда», «по-другому»"],"counter":"Назови третий вариант: «А почему не…?»"},{"type":"chat","card":"slippery-slope","messages":[{"name":"Дима","text":"Давай разрешим сотрудникам один день удалёнки в неделю."},{"name":"Руслан","text":"Сегодня один день, завтра все захотят пять, потом никто не будет работать, и компания закроется.","flag":true}],"caption":"Ни одно звено цепочки не доказано. Руслан просто пугает страшным финалом."},{"type":"concept","card":"slippery-slope","icon":"🛝","title":"Скользкая дорожка","definition":"Утверждают, что небольшой шаг обязательно запустит цепочку событий, которая закончится плохо, — но не доказывают, что каждое звено действительно последует.","signs":["«Сегодня — это, завтра — то, а потом…»","Цепочка растёт, а доказательств не прибавляется","В конце — всегда катастрофа"],"counter":"Попроси обосновать каждое звено: «Почему из первого обязательно следует второе?»","note":"Не всякая цепочка — уловка. Если каждое звено подтверждено (например, договором или законом), это обычный прогноз."}]'::jsonb, '[{"type":"binary","quote":"Если не купишь этот курс сегодня, так и останешься на месте всю жизнь.","trick":true,"explain":"Вариантов больше: купить позже, выбрать другой курс, учиться самому. Это ложная дилемма."},{"type":"binary","quote":"Если не продлим аренду до пятницы, придётся искать новый офис — так написано в договоре.","trick":false,"explain":"Последствие одно, прямое и подтверждено договором. Цепочки страшилок нет."},{"type":"choice","quote":"Разрешим смартфоны на переменах — их начнут доставать на уроках, потом перестанут учиться, и вырастет поколение неучей.","prompt":"Какая уловка?","options":["Ложная дилемма","Скользкая дорожка","Соломенное чучело"],"answer":1,"explain":"От перемен до «поколения неучей» — цепочка без единого доказательства."},{"type":"choice","quote":"Ты либо поддерживаешь мою идею, либо просто мне завидуешь.","prompt":"Какая уловка?","options":["Ложная дилемма","Скользкая дорожка","Переход на личности"],"answer":0,"explain":"Можно не поддерживать идею и не завидовать: например, видеть в ней слабое место."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Алия","text":"Может, заведём собаку?"},{"name":"Тимур","text":"Собаке нужны прогулки каждый день, надо подумать."},{"name":"Алия","text":"Я готова гулять утром, а ты вечером."},{"name":"Тимур","text":"Сначала собака, потом кошка, потом попугай — и мы превратимся в зоопарк."}],"answer":3,"explain":"Из одной собаки Тимур выводит целый зоопарк. Это скользкая дорожка. Его первое возражение про прогулки было честным."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Или учишься на отлично, или ты лентяй»","label":"Ложная дилемма"},{"quote":"«Пропустишь одну тренировку — потом бросишь спорт навсегда»","label":"Скользкая дорожка"},{"quote":"«Значит, ты хочешь, чтобы все бездельничали?»","label":"Соломенное чучело"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 3, 'Потому что так сказали', 'Ложный авторитет и апелляция к большинству', array['false-authority', 'bandwagon']::text[], '[{"type":"intro","icon":"📣","title":"День 3","text":"Иногда вместо доказательств нам предлагают просто поверить: известному человеку или толпе. Разберёмся, когда это нормально, а когда — уловка."},{"type":"chat","card":"false-authority","messages":[{"name":"Нурай","text":"Не пей этот чай, говорят, от него никакой пользы."},{"name":"Айбек","text":"Его рекламирует чемпион по боксу — значит, работает!","flag":true}],"caption":"Боксёр разбирается в боксе, а не в свойствах чая. Известность не делает его экспертом по всему."},{"type":"concept","card":"false-authority","icon":"🎓","title":"Ложный авторитет","definition":"Довод «это правда, потому что так сказал X», где X не специалист по теме — или его слова приводят вместо проверяемых фактов.","signs":["Звезда или блогер говорит не о своей сфере","Ссылка на имя вместо данных","«Учёные доказали» — без указания, кто и где"],"counter":"«В чём он эксперт? И на какие данные опирается?»","note":"Мнение настоящего эксперта по его теме — нормальный аргумент. Уловка — когда авторитет не по теме или заменяет доказательства."},{"type":"chat","card":"bandwagon","messages":[{"name":"Продавец","text":"Эту модель берут все — к нам за ней очередь!","flag":true},{"name":"Тимур","text":"А сколько держит батарея?"}],"caption":"Очередь говорит о моде или о хорошей рекламе, а не о качестве батареи. Тимур задал правильный вопрос."},{"type":"concept","card":"bandwagon","icon":"👥","title":"Апелляция к большинству","definition":"Правоту или пользу идеи обосновывают тем, сколько людей её поддерживает.","signs":["«Миллионы не могут ошибаться»","«Все уже купили, а ты?»","Популярность вместо доказательств"],"counter":"«Популярность не доказывает правоту. Почему это работает?»"}]'::jsonb, '[{"type":"binary","quote":"Этот фильм — шедевр: его посмотрели 50 миллионов человек.","trick":true,"explain":"Число зрителей говорит о популярности, а не о качестве. Это апелляция к большинству."},{"type":"binary","quote":"Метеорологи прогнозируют шторм — давай перенесём поездку.","trick":false,"explain":"Прогноз погоды от специалистов по погоде — разумное основание для решения."},{"type":"choice","quote":"Известный актёр заявил, что прививки не нужны, — значит, так и есть.","prompt":"Какая уловка?","options":["Ложный авторитет","Апелляция к большинству","Скользкая дорожка"],"answer":0,"explain":"Актёр — не иммунолог. Его слава не делает его экспертом в медицине."},{"type":"choice","quote":"Ну все же списывают на экзаменах — что тут такого?","prompt":"Какая уловка?","options":["Ложный авторитет","Апелляция к большинству","Ложная дилемма"],"answer":1,"explain":"То, что так делают многие (если это вообще правда), не делает поступок правильным."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Алия","text":"Хочу вложить деньги в эту криптовалюту."},{"name":"Дима","text":"А что ты о ней знаешь?"},{"name":"Алия","text":"В неё вложился весь мой чат — столько людей не могут ошибаться!"},{"name":"Дима","text":"Давай хотя бы почитаем, кто за ней стоит."}],"answer":2,"explain":"Количество вложившихся ничего не говорит о надёжности монеты. Это апелляция к большинству."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Так говорит известный блогер»","label":"Ложный авторитет"},{"quote":"«Так делают все»","label":"Апелляция к большинству"},{"quote":"«Начнётся с малого — закончится катастрофой»","label":"Скользкая дорожка"}]}]'::jsonb)
on conflict (course_key, day) do update set
