  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 4, 'Уйти от ответа', '«Сам такой» и отвлечение внимания', array['tu-quoque', 'red-herring']::text[], '[{"type":"intro","icon":"🏃","title":"День 4","text":"Неудобный вопрос можно не опровергать, а просто обойти: ответить упрёком или сменить тему. Научимся это замечать."},{"type":"chat","card":"tu-quoque","messages":[{"name":"Лена","text":"Ты опять опоздал на полчаса."},{"name":"Дима","text":"А ты на прошлой неделе вообще забыла про встречу!","flag":true}],"caption":"Даже если Лена забыла про встречу, опоздание Димы от этого никуда не делось. Ответа на замечание так и не прозвучало."},{"type":"concept","card":"tu-quoque","icon":"🪞","title":"«Сам такой»","definition":"Вместо ответа на замечание указывают, что критикующий сам поступает так же, — или что «у других ещё хуже».","signs":["«А ты сам…»","«А вот у них…»","Замечание повисает без ответа по существу"],"counter":"«Может, я тоже неидеален. Но давай вернёмся к вопросу: это правда проблема?»"},{"type":"chat","card":"red-herring","messages":[{"name":"Журналист","text":"Почему ремонт дороги затянулся на два года?"},{"name":"Чиновник","text":"Давайте лучше вспомним, сколько новых парков мы открыли!","flag":true}],"caption":"Парки, может, и хороши, но вопрос был про дорогу. Тему просто подменили."},{"type":"concept","card":"red-herring","icon":"🐟","title":"Отвлечение внимания","definition":"В разговор подбрасывают новую, часто более приятную или эмоциональную тему, чтобы уйти от неудобного вопроса. Классическое название — «красная селёдка».","signs":["Ответ вроде бы рядом, но не про вопрос","Внезапно обсуждается что-то более «важное»","Через минуту все забыли, о чём спорили"],"counter":"Отметь подмену и верни тему: «Интересно, но вопрос был про…»"}]'::jsonb, '[{"type":"binary","quote":"Ты говоришь, что мне вредно курить, а сам каждый день ешь фастфуд!","trick":true,"explain":"Фастфуд собеседника не делает курение полезным. Это «сам такой»."},{"type":"binary","quote":"Ты прав, я опоздал. Была пробка, но надо было выехать раньше.","trick":false,"explain":"Человек отвечает прямо на замечание и признаёт его. Уловки нет."},{"type":"choice","quote":"— Почему отчёт не готов?\n— Зато вы видели, какой у нас рекордный квартал по продажам?","prompt":"Какая уловка?","options":["Отвлечение внимания","«Сам такой»","Ложный авторитет"],"answer":0,"explain":"Продажи не отвечают на вопрос про отчёт — тему просто сменили на приятную."},{"type":"choice","quote":"Нам указывают на проблемы с экологией? Пусть сначала на себя посмотрят!","prompt":"Какая уловка?","options":["Отвлечение внимания","«Сам такой»","Апелляция к большинству"],"answer":1,"explain":"Чужие проблемы с экологией не отменяют свои. Это «сам такой»."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Тимур","text":"Ты обещал вернуть долг ещё в марте."},{"name":"Айбек","text":"Помню, извини."},{"name":"Айбек","text":"Кстати, слышал, что доллар опять подорожал? Вот где настоящая проблема!"},{"name":"Тимур","text":"Слышал. Так когда вернёшь?"}],"answer":2,"explain":"Курс доллара никак не отвечает на вопрос, когда будет возвращён долг. Это отвлечение внимания — и Тимур правильно вернул тему."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«А ты сам-то?»","label":"«Сам такой»"},{"quote":"«Давайте лучше обсудим другое»","label":"Отвлечение внимания"},{"quote":"«Ты слишком молод, чтобы рассуждать»","label":"Переход на личности"}]}]'::jsonb)
on conflict (course_key, day) do update set
