  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 5, 'Поспешные выводы', 'Поспешное обобщение и ложная причина', array['hasty-generalization', 'post-hoc']::text[], '[{"type":"intro","icon":"🔬","title":"День 5","text":"Сегодня — ошибки, которые мы часто совершаем сами: слишком быстрые выводы из пары случаев и путаница между «после» и «из-за»."},{"type":"chat","card":"hasty-generalization","messages":[{"name":"Нурай","text":"Два раза покупала в этом магазине — оба раза брак. У них всё бракованное!","flag":true},{"name":"Лена","text":"Обидно. Но два случая — ещё не весь магазин."}],"caption":"Два случая — слишком мало, чтобы судить обо всех товарах. Лена это заметила."},{"type":"concept","card":"hasty-generalization","icon":"🔍","title":"Поспешное обобщение","definition":"Из нескольких примеров делают общий вывод, хотя примеров слишком мало или они нетипичны.","signs":["«Все они такие»","«Я знаю одного — значит…»","Личный опыт выдают за правило"],"counter":"«Сколько случаев ты видел? Это правда типично?»"},{"type":"chat","card":"post-hoc","messages":[{"name":"Айбек","text":"Надел счастливые носки — и наша команда выиграла!","flag":true},{"name":"Алия","text":"А в прошлый раз, когда проиграли, они были в стирке?"}],"caption":"Победа случилась после носков, но не из-за них. Одна последовательность событий — не доказательство причины."},{"type":"concept","card":"post-hoc","icon":"🐓","title":"Ложная причина","definition":"Если одно событие случилось после другого (или они случаются вместе), его объявляют следствием первого. Но совпадение — ещё не причина.","signs":["«Как только…, сразу…»","Непонятно, как одно могло вызвать другое","Не проверены другие объяснения"],"counter":"«А что ещё могло это вызвать? Есть ли связь, кроме совпадения?»","note":"Петух кукарекает перед рассветом, но солнце встаёт не из-за него. Отсюда и иконка 🐓"}]'::jsonb, '[{"type":"binary","quote":"Поставил новые обои на телефон — и он стал быстрее работать.","trick":true,"explain":"Обои не влияют на скорость телефона. Связь только во времени — это ложная причина."},{"type":"binary","quote":"Мы опросили 2000 случайно выбранных покупателей — 70% довольны доставкой.","trick":false,"explain":"Большая случайная выборка — честное основание для общего вывода."},{"type":"choice","quote":"Мой дед курил всю жизнь и дожил до 90 — значит, курение не вредит.","prompt":"Какая уловка?","options":["Поспешное обобщение","Ложная причина","Апелляция к большинству"],"answer":0,"explain":"Один человек — не статистика. Исследования миллионов людей показывают обратное."},{"type":"choice","quote":"Я начал пить этот чай, и через неделю простуда прошла. Чай вылечил!","prompt":"Какая уловка?","options":["Поспешное обобщение","Ложная причина","Ложный авторитет"],"answer":1,"explain":"Простуда обычно и сама проходит примерно за неделю. Выздоровление случилось после чая, но не обязательно из-за него."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Дима","text":"Видела, вчера таксист нагрубил пассажиру?"},{"name":"Лена","text":"Да, неприятно."},{"name":"Дима","text":"Все таксисты — хамы, я давно говорю."},{"name":"Лена","text":"А мне на днях попался очень вежливый."}],"answer":2,"explain":"Из одного случая Дима делает вывод обо всех таксистах. Это поспешное обобщение."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Встретил двух грубых туристов — все туристы грубые»","label":"Поспешное обобщение"},{"quote":"«Чихнул — и пошёл дождь. Это я виноват!»","label":"Ложная причина"},{"quote":"«А сам-то лучше?»","label":"«Сам такой»"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 6, 'Хитрая логика', 'Круговое рассуждение и бремя доказательства', array['circular', 'burden-of-proof']::text[], '[{"type":"intro","icon":"🧩","title":"День 6","text":"Последние две уловки — самые незаметные: аргумент, который доказывает сам себя, и попытка заставить тебя опровергать чужие фантазии."},{"type":"chat","card":"circular","messages":[{"name":"Руслан","text":"Этот сайт пишет только правду."},{"name":"Нурай","text":"Откуда ты знаешь?"},{"name":"Руслан","text":"Так на нём самом написано!","flag":true}],"caption":"Сайт подтверждает сам себя. Доказательство ходит по кругу и ничего не доказывает."},{"type":"concept","card":"circular","icon":"🔄","title":"Круговое рассуждение","definition":"То, что нужно доказать, уже заложено в посылку. Аргумент ходит по кругу: вывод доказывается самим собой.","signs":["«Это правда, потому что это правда» — другими словами","Довод и вывод означают одно и то же","Источник подтверждает сам себя"],"counter":"«Ты повторил вывод другими словами. Какие есть доказательства со стороны?»"},{"type":"chat","card":"burden-of-proof","messages":[{"name":"Айбек","text":"Этот браслет укрепляет иммунитет."},{"name":"Лена","text":"А есть исследования?"},{"name":"Айбек","text":"А ты докажи, что не укрепляет!","flag":true}],"caption":"Утверждение сделал Айбек — ему и доказывать. Отсутствие опровержения не делает слова правдой."},{"type":"concept","card":"burden-of-proof","icon":"🎒","title":"Перекладывание бремени доказательства","definition":"Кто делает утверждение, тот и должен его обосновать. Уловка — требовать, чтобы другие опровергли смелое заявление, а пока не опровергли, считать его верным.","signs":["«А ты докажи, что это не так»","«Никто не опроверг — значит, правда»","Смелое утверждение без единого доказательства"],"counter":"«Утверждаешь ты — тебе и доказывать. Что у тебя есть?»"}]'::jsonb, '[{"type":"binary","quote":"Он хороший руководитель, потому что умеет хорошо руководить.","trick":true,"explain":"Довод повторяет вывод другими словами. Это круговое рассуждение."},{"type":"binary","quote":"Говоришь, новый тариф выгоднее? Покажи расчёт — сравним.","trick":false,"explain":"Просить доказательств у того, кто утверждает, — правильно."},{"type":"choice","quote":"Никто ведь не доказал, что инопланетян на Земле нет, — значит, они среди нас.","prompt":"Какая уловка?","options":["Круговое рассуждение","Перекладывание бремени доказательства","Ложная причина"],"answer":1,"explain":"Отсутствие опровержения — не доказательство. Доказывать должен тот, кто утверждает."},{"type":"choice","quote":"Это лучший ресторан города — ведь лучше него в городе ничего нет.","prompt":"Какая уловка?","options":["Круговое рассуждение","Апелляция к большинству","Поспешное обобщение"],"answer":0,"explain":"«Лучший» и «лучше него нет» — одно и то же. Довод доказывает сам себя."},{"type":"spot","prompt":"Найди реплику с уловкой","messages":[{"name":"Алия","text":"Говорят, если пить воду с лимоном, похудеешь на 10 кг за месяц."},{"name":"Тимур","text":"Звучит слишком хорошо. Откуда это?"},{"name":"Алия","text":"Не знаю. Но ты же не можешь доказать, что это не работает!"},{"name":"Тимур","text":"Доказывать должен тот, кто обещает минус 10 кг."}],"answer":2,"explain":"Алия перекладывает бремя доказательства на Тимура. Тимур ответил правильно."},{"type":"match","prompt":"Соедини фразу и приём","pairs":[{"quote":"«Это правда, потому что это правда»","label":"Круговое рассуждение"},{"quote":"«Докажи, что я неправ»","label":"Бремя доказательства"},{"quote":"«Миллионы не могут ошибаться»","label":"Апелляция к большинству"}]}]'::jsonb)
on conflict (course_key, day) do update set
  title = excluded.title, subtitle = excluded.subtitle, cards = excluded.cards,
  theory = excluded.theory, practice = excluded.practice;
insert into public.course_days (course_key, day, title, subtitle, cards, theory, practice)
values ('logic-fallacies', 7, 'Финал', 'Как спорить честно + итоговый тест', '{}'::text[], '[{"type":"intro","icon":"🏁","title":"Финальный день","text":"Ты знаешь 12 уловок. Осталось три правила честного спора, короткое повторение и итоговый тест. Сдашь — получишь сертификат."},{"type":"tip","icon":"🤝","title":"Правило 1. Перескажи собеседника","text":"Прежде чем возражать, перескажи позицию собеседника так, чтобы он сказал: «Да, именно это я и имел в виду». Так ты не построишь соломенное чучело даже случайно — и человек почувствует, что его услышали."},{"type":"tip","icon":"🎯","title":"Правило 2. Спорь с доводом, а не с человеком","text":"Обсуждай, верен ли аргумент, а не кто его сказал. Если сомневаешься в источнике — проверь факты, а не характер собеседника."},{"type":"tip","icon":"🧊","title":"Правило 3. Называй уловку спокойно","text":"Не «Ха, это переход на личности, ты проиграл!», а «Давай вернёмся к самому доводу». И помни: заметить уловку не значит доказать, что вывод собеседника неверен. Плохой аргумент бывает и у правильной мысли."}]'::jsonb, '[]'::jsonb)
on conflict (course_key, day) do update set
